diff --git a/cmd/entire/cli/agent/antigravity/hooks.go b/cmd/entire/cli/agent/antigravity/hooks.go
index a2ecf1e18..b52b241ad 100644
--- a/cmd/entire/cli/agent/antigravity/hooks.go
+++ b/cmd/entire/cli/agent/antigravity/hooks.go
@@ -8,6 +8,7 @@ import (
 	"fmt"
 	"os"
 	"os/exec"
+	"strconv"

 	"github.com/entireio/cli/cmd/entire/cli/agent"
 	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
@@ -266,6 +267,60 @@ func (a *AntigravityAgent) AreHooksInstalled(ctx context.Context) (bool, error)
 // repos, in which case agy kills the hook mid-turn-end with no trace.
 const stopHookTimeoutSeconds = 300

+var _ agent.HookTimeoutRepairer = (*AntigravityAgent)(nil)
+
+// RepairHookTimeouts implements agent.HookTimeoutRepairer. Installs from before
+// stopHookTimeoutSeconds leave agy's 30s default on Stop, which is shorter than
+// the turn-end budget derived from it. It only adds a missing Stop timeout to
+// the "entire" entry, editing raw JSON so keys Entire does not model survive,
+// and skips an entry that does not parse rather than rewriting it.
+func (a *AntigravityAgent) RepairHookTimeouts(ctx context.Context) (bool, error) {
+	cfg, err := a.hookConfig(ctx)
+	if err != nil {
+		return false, err
+	}
+	data, err := cfg.Read()
+	if err != nil {
+		if errors.Is(err, os.ErrNotExist) {
+			return false, nil
+		}
+		return false, err //nolint:wrapcheck // agent.HookConfigFile already names the file in its error
+	}
+	var rawFile map[string]json.RawMessage
+	if err := json.Unmarshal(data, &rawFile); err != nil {
+		return false, fmt.Errorf("failed to parse hooks.json: %w", err)
+	}
+	var entry map[string]json.RawMessage
+	if err := json.Unmarshal(rawFile["entire"], &entry); err != nil || entry == nil {
+		return false, nil //nolint:nilerr // an absent or unparseable entry is left for install to replace
+	}
+	var stop []map[string]json.RawMessage
+	if err := json.Unmarshal(entry["Stop"], &stop); err != nil {
+		return false, nil //nolint:nilerr // an unparseable Stop list is left for install to replace
+	}
+
+	changed := false
+	for _, handler := range stop {
+		if _, ok := handler["timeout"]; !ok {
+			handler["timeout"] = json.RawMessage(strconv.Itoa(stopHookTimeoutSeconds))
+			changed = true
+		}
+	}
+	if !changed {
+		return false, nil
+	}
+	if entry["Stop"], err = jsonutil.MarshalWithNoHTMLEscape(stop); err != nil {
+		return false, fmt.Errorf("failed to marshal Stop hooks: %w", err)
+	}
+	if rawFile["entire"], err = jsonutil.MarshalWithNoHTMLEscape(entry); err != nil {
+		return false, fmt.Errorf("failed to marshal hook config: %w", err)
+	}
+	if err := writeHooksFile(rawFile, cfg); err != nil {
+		return false, err
+	}
+	return true, nil
+}
+
 // buildEntireHookConfig constructs the HookConfig for the "entire" entry for
 // the host this binary runs on.
 func buildEntireHookConfig() HookConfig {
diff --git a/cmd/entire/cli/doctor.go b/cmd/entire/cli/doctor.go
index 6dca89fc7..3cf59cc8a 100644
--- a/cmd/entire/cli/doctor.go
+++ b/cmd/entire/cli/doctor.go
@@ -1412,8 +1412,9 @@ func checkRetiredDenyRule(cmd *cobra.Command) {
 }

 // checkHookTimeouts gives Entire's hooks the timeouts a config written by an
-// older CLI lacks, so a stalled `entire` launch cannot block the agent until
-// its own default timeout. It repairs without asking for the reason
+// older CLI lacks, so the agent's own default does not apply instead: a longer
+// one lets a stalled `entire` launch block the agent, and a shorter one (agy's
+// 30s on Stop) kills a turn-end hook before it saves session state. It repairs without asking for the reason
 // checkRetiredDenyRule does: it only sets a timeout on a hook Entire wrote that
 // has none, so nothing the user chose is touched. As there, a repair error is
 // logged rather than printed.
@@ -1428,8 +1429,8 @@ func checkHookTimeouts(cmd *cobra.Command) {
 		},
 		func(w io.Writer, ag agent.Agent) {
 			fmt.Fprintf(w, "%s hooks: MISSING TIMEOUTS\n", ag.Type())
-			fmt.Fprintln(w, "  Some Entire hooks had no timeout, so a stalled `entire` launch could block")
-			fmt.Fprintln(w, "  the agent until its own default timeout.")
+			fmt.Fprintln(w, "  Some Entire hooks had no timeout, so the agent applied its own default,")
+			fmt.Fprintln(w, "  which can block the agent too long or stop a hook before it finishes.")
 			fmt.Fprintln(w, "  ✓ Fixed: timeouts added (your own hooks and timeouts are untouched).")
 		})
 }
